        if(!f)throw new Error(`找不到 ${path}`);
        const url=URL.createObjectURL(f);urls.push(url);pack.regions[region][channel]=url;
      }
      return await this.apply(pack);
    }finally{urls.forEach(url=>URL.revokeObjectURL(url));}
  }
